sp_widget.client_script:
api.controller = function($scope) {
    var c = this;

    // ── Core state ──────────────────────────────────────────────
    c.data.calc                  = {};
    c.data.submitted             = false;
    c.data.submitting            = false;
    c.data.saving                = false;
    c.data.searchError           = '';
    c.data.submitError           = '';
    c.data.searchTerm            = '';
    c.data.searchResults         = [];
    c.data.selectedCustomerSysId = '';
    c.data.sites                 = [];
    c.data.sitesCount            = 0;
    c.data.sitesTotalRequested   = 0;
    c.data.sitesValidationError  = '';

    // ── Autocomplete state ──────────────────────────────────────
    c.data.suggestions           = [];
    c.data.suggestionIndex       = -1;
    c.data.suggestionSelected    = false;
    c.data.suggestionTimer       = null;

    // ── Selected single trade row ───────────────────────────────
    c.data.selectedTradeRow      = null;

    // ── Debounced live suggestions ──────────────────────────────
    c.onSearchChange = function() {
        c.data.searchResults         = [];
			c.data.agingTable = [];
        c.data.searchError           = '';
        c.data.selectedCustomerSysId = '';
        c.data.suggestionSelected    = false;
        c.data.suggestionIndex       = -1;
        c.data.selectedTradeRow      = null;
        c.clearCustomerData();

        var term = (c.data.searchTerm || '').trim();
        if (term.length < 3) {
            c.data.suggestions = [];
            return;
        }

        if (c.data.suggestionTimer) clearTimeout(c.data.suggestionTimer);
        c.data.suggestionTimer = setTimeout(function() {
            c.fetchSuggestions(term);
        }, 300);
    };

    // ── Fetch suggestions ───────────────────────────────────────
    c.fetchSuggestions = function(term) {
        c.server.get({
            action: 'searchCustomers',
            searchTerm: term
        }).then(function(r) {
            if (r.data.customers && r.data.customers.length > 0) {
                c.data.suggestions = r.data.customers.slice(0, 8);
            } else {
                c.data.suggestions = [];
            }
            $scope.$apply();
        });
    };

    // ── Pick a suggestion from dropdown ─────────────────────────
    // This just fills the search box and triggers a full search
    c.pickSuggestion = function(s) {
   c.data.searchTerm         = s.pan || s.customer_code_sap;
        c.data.suggestions        = [];
        c.data.suggestionSelected = true;
        c.searchCustomers();
    };

    // ── Keyboard nav ────────────────────────────────────────────
    c.onSearchKeydown = function(evt) {
        var len = c.data.suggestions.length;
        if (len === 0) return;
        if (evt.keyCode === 40) {
            evt.preventDefault();
            c.data.suggestionIndex = Math.min(c.data.suggestionIndex + 1, len - 1);
        } else if (evt.keyCode === 38) {
            evt.preventDefault();
            c.data.suggestionIndex = Math.max(c.data.suggestionIndex - 1, -1);
        } else if (evt.keyCode === 13) {
            evt.preventDefault();
            if (c.data.suggestionIndex >= 0) {
                c.pickSuggestion(c.data.suggestions[c.data.suggestionIndex]);
            } else {
                c.searchCustomers();
            }
        } else if (evt.keyCode === 27) {
            c.data.suggestions     = [];
            c.data.suggestionIndex = -1;
        }
    };

    // ── Full search → shows all customer cards ──────────────────
    c.searchCustomers = function() {
        var term = (c.data.searchTerm || '').trim();
        if (term.length < 3) {
            c.data.searchError = 'Enter at least 3 characters to search';
            return;
        }

        c.data.searchError           = '';
        c.data.searchResults         = [];
        c.data.selectedCustomerSysId = '';
        c.data.selectedTradeRow      = null;
        c.data.suggestions           = [];
        c.clearCustomerData();

        c.server.get({
            action: 'searchCustomers',
            searchTerm: term
        }).then(function(r) {
            if (r.data.customers && r.data.customers.length > 0) {
                c.data.searchResults = r.data.customers;
							        c.loadPanTableCredits();

                // Do NOT auto-select — let user click a card
            } else {
                c.data.searchResults = [];
                c.data.searchError   = 'No customers found';
            }
        });
    };
// ── PAN TABLE CREDIT FETCH ──
c.loadPanTableCredits = function() {

    if (!c.data.searchResults || c.data.searchResults.length === 0) return;

    var totalPanCL = 0; // 🔥 total accumulator

    c.data.searchResults.forEach(function(cust) {

        c.server.get({
            action: 'getCreditLimit',
            customer_code: cust.customer_code_sap
        }).then(function(res) {

            var credit = parseFloat(res.data.credit) || 0;

            cust.live_credit = credit;

            // 🔥 ADD TO TOTAL
            totalPanCL += credit;

            // 🔥 UPDATE GLOBAL PAN LEVEL CL
            c.data.panlevelCL = totalPanCL;

        });

    });
};
    // ── User clicks a customer card ─────────────────────────────
c.selectCustomer = function(cust) {



    if (!cust.is_my_customer) {
        alert("You can only select customers assigned to you.");
        return;
    }        // If same customer clicked again — deselect
        if (c.data.selectedCustomerSysId === cust.sys_id) return;

        c.data.selectedCustomerSysId = cust.sys_id;
        c.data.customerSysId         = cust.sys_id;
        c.data.customerName          = cust.customer_name;
        c.data.customerType          = cust.customer_type;
        c.data.segment               = cust.segment;
			c.data.segment = cust.segment;
	 c.data.depot                  = cust.depot;
        c.data.zone                  = cust.zone;
        c.data.region                = cust.region;
        c.data.pan                   = cust.pan;
        c.data.cg2Code               = cust.cg2_code;
        c.data.constitution          = cust.constitution;
        c.data.isListed              = cust.is_listed;
	c.data.agingTable = cust.aging_table || [];
        c.data.vintageDays           = cust.vintage_days;
        c.data.currentLimit          = cust.current_credit_limit / 100000;
        c.data.avgMonthlySales       = cust.avg_monthly_sales;
        c.data.orderRate             = cust.order_rate || 7000;
        c.data.outstanding           = cust.outstanding || 0;
			c.data.panLevelSD = cust.pan_level_sd || 0;
//	c.data.panlevelCL = cust.pan_level_cl || 0;
        c.data.activeSD              = (cust.customer_type === 'Trade') ? (cust.current_sd || 0) : 0;

        // Build the single trade row for Section 2
        if (cust.customer_type === 'Trade') {
            c.data.selectedTradeRow = {
                customer_code:        cust.customer_code_sap,
                customer_sys_id:      cust.sys_id,
                active_sd:            cust.current_sd || 0,
                current_limit:        cust.current_credit_limit || 0,
                outstanding:          cust.outstanding || 0,
                requested_additional: 0,
                total_requested:      cust.current_credit_limit || 0
            };
					// 🔥 CALL SOAP API WHEN CUSTOMER IS SELECTED
c.server.get({
    action: 'getCreditLimit',
    customer_code: cust.customer_code_sap
}).then(function(response) {

    // store live credit
c.data.liveCreditLimit = parseFloat(response.data.credit) || 0;
    // 🔥 OVERRIDE current limit
    if (c.data.selectedTradeRow) {
var credit = parseFloat(response.data.credit) || 0;

c.data.selectedTradeRow.current_limit = credit;
c.data.selectedTradeRow.total_requested = credit; // 🔥 important sync   
		}

});
           c.data.requestedLimit = 0;
					c.data.calc = {}; 
        } else {
            c.data.selectedTradeRow = null;
        }

        // Non-Trade: load sites
        if (cust.customer_type === 'Non-Trade') {
            c.loadSites(cust.sys_id, cust.pan);
        }

        // Recalculate
        if (c.data.requestedLimit > 0) c.recalculate();
    };

    // ── Calculate for the single selected trade customer ────────
c.calculateSingleTrade = function() {

    if (!c.data.selectedTradeRow) return;

    var current = parseFloat(c.data.selectedTradeRow.current_limit) || 0;

    var raw = c.data.selectedTradeRow.requested_additional;

    // ✅ STEP 1: Handle EMPTY input
    if (raw === '' || raw === null || raw === undefined) {
        c.data.selectedTradeRow.total_requested = current;
        c.data.requestedLimit = 0;
        c.data.calc = {};   // 🔥 CLEAR live calculation
        return;
    }

    var add = parseFloat(raw);

    var total = current + add;

    // ❌ Only block NEGATIVE
    if (total < 0) {
        alert("Total Limit Requested cannot be negative");

        c.data.selectedTradeRow.requested_additional = 0;
        c.data.selectedTradeRow.total_requested = current;
        c.data.requestedLimit = current;
        return;
    }

    // ✅ Valid
    c.data.selectedTradeRow.total_requested = total;
    c.data.requestedLimit = total;

    // 🚨 IMPORTANT: only calculate if > 0
    if (total > 0) {
        c.recalculate();
    } else {
        c.data.calc = {}; // hide panel when total = 0
    }
};

    // ── Clear customer data ─────────────────────────────────────
    c.clearCustomerData = function() {
        c.data.customerSysId         = '';
        c.data.customerName          = '';
        c.data.customerType          = '';
        c.data.segment               = '';
        c.data.calc                  = {};
        c.data.activeSD              = 0;
        c.data.outstanding           = 0;
        c.data.sites                 = [];
        c.data.sitesCount            = 0;
        c.data.sitesTotalRequested   = 0;
        c.data.selectedTradeRow      = null;
        c.data.requestedLimit        = 0;
    };

    // ── Load sites for Non-Trade ────────────────────────────────
    c.loadSites = function(customerSysId, pan) {
        c.server.get({
            action: 'loadSites',
            customerSysId: customerSysId,
            pan: pan
        }).then(function(r) {
            if (r.data.sites && r.data.sites.length > 0) {
                c.data.sites      = r.data.sites;
                c.data.sitesCount = r.data.sites.length;
                c.recalculateSites();
            } else {
                c.data.sites      = [];
                c.data.sitesCount = 0;
            }
        });
    };

    // ── Recalculate sites (Non-Trade) ───────────────────────────
    c.recalculateSites = function() {
        if (!c.data.sites || c.data.sites.length === 0) {
            c.data.sitesTotalRequested = 0;
            c.data.sitesCount = 0;
            return;
        }
        var total = 0, count = 0;
        c.data.sites.forEach(function(site) {
            var req = parseFloat(site.requested_limit) || 0;
            if (req > 0) { total += req; count++; }
        });
        c.data.sitesTotalRequested = total / 100000;
        c.data.sitesCount          = count;
        c.data.sitesValidationError = (c.data.sitesTotalRequested === 0)
            ? 'All requested credit must be allocated to sites. Total cannot be 0.'
            : '';
        c.data.requestedLimit = total;
        c.recalculate();
    };

    // ── Live recalculate ────────────────────────────────────────
    c.recalculate = function() {
        if (c.data.customerType === 'Non-Trade') return;
        var req = parseFloat(c.data.requestedLimit) || 0;
        if (req <= 0 || !c.data.customerSysId) { c.data.calc = {}; return; }

        c.server.get({
            action:          'calculate',
            customerType:    c.data.customerType || 'Trade',
            customerSysId:   c.data.customerSysId,
            requestedLimit:  req,
            activeSD:        parseFloat(c.data.activeSD)        || 0,
            outstanding:     parseFloat(c.data.outstanding)     || 0,
            avgMonthlySales: parseFloat(c.data.avgMonthlySales) || 0,
            salesLastMonth:  parseFloat(c.data.salesLastMonth)  || 0,
            salesPrevMonth:  parseFloat(c.data.salesPrevMonth)  || 0,
            segment:         c.data.segment   || 'Cement',
            cg2Code:         c.data.cg2Code   || '',
            vintageDays:     parseInt(c.data.vintageDays) || 0
        }).then(function(r) {
    if (r.data.calc) {
        c.data.calc = angular.copy(r.data.calc);  // 🔥 FORCE UI REFRESH
    }
});
    };

    // ── Save Draft ──────────────────────────────────────────────
    c.saveDraft = function() {
        c.data.saving = true;
        c.server.get({ action: 'saveDraft', form: c.buildPayload() })
        .then(function(r) {
            c.data.saving        = false;
            c.data.draftSysId    = r.data.sysId;
            c.data.requestNumber = r.data.number;
        });
    };

    // ── Submit ──────────────────────────────────────────────────
 c.submit = function() {
    c.data.submitError = '';

    // 1. Must have a customer selected
    if (!c.data.selectedCustomerSysId) {
        c.data.submitError = 'Please select a customer.';
        return;
    }

    // 2. Segment must exist (debug: log it)
   /* if (!c.data.segment || c.data.segment === '') {
        c.data.submitError = 'Customer segment is missing. Please re-select the customer.';
        return;
    } */

    // 3. For Trade, must have entered an additional limit
    if (c.data.customerType === 'Trade') {
        if (!c.data.selectedTradeRow) {
            c.data.submitError = 'Please select a customer first.';
            return;
        }
        var addl = parseFloat(c.data.selectedTradeRow.requested_additional) || 0;
        if (addl <= 0) {
            c.data.submitError = 'Please enter the additional limit amount to request.';
            return;
        }
    }

    // 4. Business justification — always required
    if (!c.data.justification || c.data.justification.trim().length < 20) {
        c.data.submitError = 'Business justification must be at least 20 characters.';
        return;
    }

    // 5. Deviation justification — only if deviation
    if (c.data.calc && c.data.calc.isDeviation) {
        if (!c.data.deviationJustification || c.data.deviationJustification.trim().length < 20) {
            c.data.submitError = 'Deviation justification is required (min 20 characters).';
            return;
        }
    }

    // 6. Non-Trade site validation
    if (c.data.customerType === 'Non-Trade') {
        if (!c.data.sitesTotalRequested || c.data.sitesTotalRequested === 0) {
            c.data.submitError = 'All requested credit must be allocated to sites. Total cannot be 0.';
            return;
        }
        if (c.data.sitesValidationError) {
            c.data.submitError = c.data.sitesValidationError;
            return;
        }
    }

    // ✅ All validations passed — submit
    c.data.submitting  = true;
    c.data.submitError = '';

    c.server.get({ action: 'submit', form: c.buildPayload() })
  .then(function(r) {
        c.data.submitting = false;
        if (r.data.success) {
            c.data.submitted        = true;
            c.data.requestNumber    = r.data.requestNumber;
            c.data.approverRole     = r.data.approverRole;
            c.data.isDeviation      = r.data.isDeviation;
            // ── Clear calc so no stale deviation alerts show ──
            c.data.calc             = {};
        } else {
            c.data.submitError = r.data.error || 'Submission failed. Please try again.';
        }
    }).catch(function(err) {
        c.data.submitting  = false;
        c.data.submitError = 'Server error. Please try again.';
    });
};

    // ── Reset ───────────────────────────────────────────────────
    c.resetForm = function() {
        c.data = {
            calc: {}, submitted: false, submitting: false, saving: false,
            searchTerm: '', searchResults: [], selectedCustomerSysId: '',
            suggestions: [], suggestionIndex: -1, suggestionSelected: false,
            sites: [], sitesCount: 0, sitesTotalRequested: 0,
            selectedTradeRow: null
        };
    };

    // ── Build payload ───────────────────────────────────────────
    c.buildPayload = function() {
        var payload = {
            customerSysId:         c.data.selectedCustomerSysId,
            customerType:          c.data.customerType,
            segment:               c.data.segment,
            requestedLimit:        c.data.requestedLimit,
            activeSD:              c.data.activeSD              || 0,
            outstanding:           c.data.outstanding           || 0,
					currentCreditLimit: (c.data.selectedTradeRow && c.data.selectedTradeRow.current_limit) || 0,
					panLevelCL: c.data.panlevelCL || 0,
            avgMonthlySales:       c.data.avgMonthlySales       || 0,
            salesLastMonth:        c.data.salesLastMonth        || 0,
            salesPrevMonth:        c.data.salesPrevMonth        || 0,
            chequeBounces:         c.data.chequeBounces         || 0,
            marketPerception:      c.data.marketPerception      || '',
            justification:         c.data.justification,
            deviationJustification: c.data.deviationJustification || '',
            isDeviation:           c.data.calc.isDeviation,
            vintageDays:           c.data.vintageDays           || 0,
            draftSysId:            c.data.draftSysId            || ''
        };

        // Trade: send the single selected customer
        if (c.data.customerType === 'Trade' && c.data.selectedTradeRow) {
            payload.tradeCustomers = [{
                customer_code:        c.data.selectedTradeRow.customer_code,
                current_limit:        c.data.selectedTradeRow.current_limit,
                active_sd:            c.data.selectedTradeRow.active_sd,
                outstanding:          c.data.selectedTradeRow.outstanding,
                requested_additional: c.data.selectedTradeRow.requested_additional,
                total_requested:      c.data.selectedTradeRow.total_requested
            }];
        }

        // Non-Trade: send sites
        if (c.data.customerType === 'Non-Trade' && c.data.sites && c.data.sites.length > 0) {
            payload.sites = c.data.sites.map(function(s) {
                return {
                    site_code:         s.site_code,
                    depot:             s.depot,
                    location:          s.location,
                    current_limit:     parseFloat(s.current_limit)      || 0,
                    outstanding:       parseFloat(s.outstanding)         || 0,
                    project_potential: parseFloat(s.project_potential)   || 0,
                    monthly_volume:    parseFloat(s.monthly_volume)      || 0,
                    requested_limit:   parseFloat(s.requested_limit)     || 0
                };
            }).filter(function(s) { return s.requested_limit > 0; });
        }

        return payload;
    };
};

sp_widget.css:
  /* ============================================================
     CLM WIDGET — COMPLETE CSS (UltraTech Theme)
     FULLY RESPONSIVE + MOBILE OPTIMIZED
     Brand Colors: Black #000000 | Neon Yellow #FFF21A | White #FFFFFF
     ============================================================ */

  /* ── Base ── */
  .clm-widget {
    font-family: "Source Sans Pro", "Helvetica Neue", Helvetica, Arial, sans-serif;
    width: 100%;
    max-width: none;
    margin: 0;
    padding: 0;
    color: #1a1a1a;
    box-sizing: border-box;
  }
.clm-aging-table {
  width: 100%;
  border-collapse: collapse;
  font-size: 13px;
  min-width: 800px;
}

.clm-aging-table th {
  background: #000;
  color: #FFF21A;
  padding: 8px;
  border: 1px solid #ddd;
}

.clm-aging-table td {
  padding: 8px;
  border: 1px solid #ddd;
  text-align: right;
}

.clm-aging-table td:first-child {
  text-align: left;
  font-weight: 600;
}

.clm-pan-table {
  width: 100%;
  border-collapse: collapse;
  margin-top: 8px;
  font-size: 13px;
}
.clm-pan-table thead tr {
  background: #000;
  color: #FFF21A;
}
.clm-pan-table th {
  padding: 10px 12px;
  text-align: left;
  font-size: 11px;
  font-weight: 700;
  text-transform: uppercase;
  letter-spacing: 0.5px;
  white-space: nowrap;
}
.clm-pan-row {
  cursor: pointer;
  border-bottom: 1px solid #f0f0f0;
  transition: background 0.15s;
}
.clm-pan-row:hover { background: #fffde7; }
.clm-pan-row-selected { background: #fffde7 !important; border-left: 3px solid #000; }
.clm-pan-table td { padding: 10px 12px; color: #1a1a1a; }
.clm-row-check {
  display: inline-flex; align-items: center; justify-content: center;
  width: 20px; height: 20px; background: #FFF21A;
  border-radius: 50%; font-size: 11px; font-weight: 700; color: #000;
}
/* ── PAN Search Table ── */
.clm-pan-table-wrapper {
  overflow-x: auto;
  border-radius: 6px;
  border: 1px solid #e0e0e0;
}

.clm-pan-table {
  width: 100%;
  border-collapse: collapse;
  font-size: 13px;
  min-width: 700px;
}

.clm-pan-table thead tr {
  background: #000000;
  color: #FFF21A;
}

.clm-pan-table th {
  padding: 11px 14px;
  text-align: left;
  font-size: 11px;
  font-weight: 700;
  text-transform: uppercase;
  letter-spacing: 0.6px;
  white-space: nowrap;
}

.clm-pan-row {
  cursor: pointer;
  border-bottom: 1px solid #f0f0f0;
  transition: background 0.15s;
}

.clm-pan-row:hover {
  background: #fffde7;
}

.clm-pan-row-selected {
  background: #fffde7 !important;
  border-left: 4px solid #000000;
}

.clm-pan-table td {
  padding: 11px 14px;
  color: #1a1a1a;
  vertical-align: middle;
}

.clm-pan-name {
  font-size: 13px;
  font-weight: 700;
  color: #000000;
}

.clm-pan-type {
  font-size: 11px;
  margin-top: 2px;
  font-weight: 600;
}

.clm-pan-num {
  font-weight: 600;
  font-size: 13px;
  white-space: nowrap;
}

.clm-pan-mult {
  text-align: center;
}

.clm-mult-badge {
  display: inline-block;
  background: #000000;
  color: #FFF21A;
  font-size: 12px;
  font-weight: 700;
  padding: 3px 10px;
  border-radius: 12px;
  letter-spacing: 0.3px;
}

.clm-row-check {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  width: 22px;
  height: 22px;
  background: #FFF21A;
  border-radius: 50%;
  font-size: 12px;
  font-weight: 700;
  color: #000000;
}

.clm-pan-hint {
  font-size: 11px;
  color: #888888;
  font-style: italic;
  margin-top: 10px;
  text-align: right;
}
/* ── Autocomplete Wrapper ── */
.clm-search-autocomplete {
  position: relative;
}

/* ── Suggestions Dropdown ── */
.clm-suggestions-dropdown {
  position: absolute;
  top: calc(100% + 4px);
  left: 0;
  right: 0;
  z-index: 9999;
  background: #fff;
  border: 1px solid #e0e0e0;
  border-radius: 6px;
  box-shadow: 0 6px 20px rgba(0,0,0,0.12);
  overflow: hidden;
  max-height: 280px;
  overflow-y: auto;
}

.clm-suggestion-item {
  display: flex;
  align-items: center;
  gap: 10px;
  padding: 10px 14px;
  cursor: pointer;
  border-bottom: 1px solid #f5f5f5;
  transition: background 0.12s;
}

.clm-suggestion-item:last-child {
  border-bottom: none;
}

.clm-suggestion-item:hover,
.clm-suggestion-active {
  background: #fffde7;
}

.clm-suggestion-icon {
  font-size: 14px;
  flex-shrink: 0;
  color: #aaa;
}

.clm-suggestion-text {
  flex: 1;
  overflow: hidden;
}

.clm-suggestion-name {
  display: block;
  font-size: 13px;
  font-weight: 700;
  color: #000;
  white-space: nowrap;
  overflow: hidden;
  text-overflow: ellipsis;
}

.clm-suggestion-meta {
  display: block;
  font-size: 11px;
  color: #888;
  margin-top: 1px;
}

.clm-suggestion-code {
  font-size: 11px;
  font-weight: 700;
  color: #000;
  background: #f0f0f0;
  padding: 2px 8px;
  border-radius: 10px;
  flex-shrink: 0;
}

  /* ── Header ── */
  .clm-header {
    display: flex;
    align-items: center;
    justify-content: space-between;
    background: #000000;
    color: #fff;
    padding: 20px 28px;
    border-radius: 8px 8px 0 0;
    margin-bottom: 0;
    border-bottom: 3px solid #FFF21A;
    flex-wrap: wrap;
    gap: 12px;
  }
  .clm-title {
    font-size: 20px;
    font-weight: 600;
    letter-spacing: 0.3px;
    color: #ffffff;
  }
  .clm-subtitle {
    font-size: 13px;
    color: rgba(255, 242, 26, 0.75);
    margin-top: 2px;
    width: 100%;
  }
  .clm-request-badge {
    background: #FFF21A;
    border: 1px solid #FFF21A;
    color: #000000;
    padding: 4px 14px;
    border-radius: 20px;
    font-size: 13px;
    font-weight: 700;
    letter-spacing: 0.5px;
    margin-left: auto;
  }

  /* ── Section ── */
  .clm-section {
    background: #fff;
    border: 1px solid #e0e0e0;
    border-top: none;
    padding: 24px 28px;
  }
  .clm-section:last-of-type {
    border-radius: 0 0 8px 8px;
  }
  .clm-section-title {
    font-size: 14px;
    font-weight: 700;
    color: #000000;
    text-transform: uppercase;
    letter-spacing: 0.8px;
    margin-bottom: 18px;
    display: flex;
    align-items: center;
    gap: 10px;
  }
  .clm-section-num {
    width: 24px;
    height: 24px;
    background: #FFF21A;
    color: #000000;
    border-radius: 50%;
    font-size: 12px;
    font-weight: 700;
    display: inline-flex;
    align-items: center;
    justify-content: center;
    flex-shrink: 0;
  }

  /* ── Form Layout ── */
  .clm-row {
    display: flex;
    gap: 20px;
    flex-wrap: wrap;
    margin-bottom: 16px;
  }
  .clm-row:last-child {
    margin-bottom: 0;
  }
  .clm-field {
    flex: 1;
    min-width: 200px;
  }
  .clm-field label {
    display: block;
    font-size: 13px;
    font-weight: 600;
    color: #4a4a4a;
    margin-bottom: 6px;
  }
  .req {
    color: #e74c3c;
    margin-left: 2px;
  }

  .clm-input,
  .clm-textarea {
    width: 100%;
    padding: 9px 12px;
    border: 1px solid #cccccc;
    border-radius: 5px;
    font-size: 14px;
    color: #1a1a1a;
    background: #fff;
    transition: border-color 0.15s, box-shadow 0.15s;
    box-sizing: border-box;
  }
  .clm-input:focus,
  .clm-textarea:focus {
    outline: none;
    border-color: #000000;
    box-shadow: 0 0 0 3px rgba(255, 242, 26, 0.4);
  }
  .clm-input[readonly] {
    background: #f5f5f5;
    color: #888888;
    cursor: default;
  }
  .clm-textarea {
    resize: vertical;
    min-height: 90px;
    line-height: 1.5;
  }
  .clm-textarea-danger {
    border-color: #e74c3c;
  }
  .clm-textarea-danger:focus {
    border-color: #c0392b;
    box-shadow: 0 0 0 3px rgba(231, 76, 60, 0.12);
  }

  /* Input with button */
  .clm-input-group {
    display: flex;
    gap: 8px;
  }
  .clm-input-group .clm-input {
    flex: 1;
  }
  .clm-input-btn {
    padding: 9px 16px;
    background: #FFF21A;
    color: #000000;
    border: none;
    border-radius: 5px;
    font-size: 13px;
    font-weight: 700;
    cursor: pointer;
    white-space: nowrap;
    transition: background 0.15s;
  }
  .clm-input-btn:hover {
    background: #e6d900;
  }
  .clm-input-btn:disabled {
    background: #e0e0e0;
    color: #999999;
    cursor: not-allowed;
  }

  .clm-field-hint {
    font-size: 12px;
    color: #888888;
    margin-top: 4px;
  }
  .clm-field-msg {
    font-size: 12px;
    margin-top: 4px;
  }
  .clm-error {
    color: #e74c3c;
  }

  /* ── Customer Strip ── */
  .clm-customer-strip {
    display: flex;
    flex-wrap: wrap;
    gap: 8px;
    margin-top: 16px;
    padding: 12px 16px;
    background: #f5f5f5;
    border-radius: 6px;
    border: 1px solid #e0e0e0;
  }
  .clm-strip-item {
    display: flex;
    flex-direction: column;
    gap: 2px;
    min-width: 100px;
  }
  .clm-strip-label {
    font-size: 11px;
    font-weight: 700;
    text-transform: uppercase;
    letter-spacing: 0.5px;
    color: #888888;
  }
  .clm-strip-value {
    font-size: 13px;
    font-weight: 600;
    color: #1a1a1a;
  }

  /* Customer type colors */
  .clm-type-trade {
    color: #000000;
  }
  .clm-type-nontrade {
    color: #8e44ad;
  }
  .clm-type-key {
    color: #c8860a;
  }

  /* ── Calc Panel ── */
  .clm-calc-panel {
    background: #f9f9f9;
    border: 1px solid #e0e0e0;
    border-top: 3px solid #FFF21A;
    border-bottom: none;
    padding: 20px 28px;
  }
  .clm-calc-title {
    font-size: 12px;
    font-weight: 700;
    text-transform: uppercase;
    letter-spacing: 1px;
    color: #000000;
    margin-bottom: 16px;
    display: flex;
    align-items: center;
    gap: 10px;
  }
  .clm-calc-grid {
    display: grid;
    grid-template-columns: repeat(auto-fill, minmax(140px, 1fr));
    gap: 12px;
    margin-bottom: 16px;
  }
  .clm-calc-card {
    background: #fff;
    border: 1px solid #e0e0e0;
    border-radius: 6px;
    padding: 12px 14px;
  }
  .clm-calc-card-safe {
    border-color: #a9dfbf;
    background: #f0faf4;
  }
  .clm-calc-card-danger {
    border-color: #f5b7b1;
    background: #fdf3f2;
  }
  .clm-calc-label {
    font-size: 11px;
    font-weight: 700;
    text-transform: uppercase;
    letter-spacing: 0.5px;
    color: #888888;
    margin-bottom: 6px;
  }
  .clm-calc-value {
    font-size: 20px;
    font-weight: 700;
    color: #000000;
    line-height: 1.2;
  }
  .clm-calc-sub {
    font-size: 11px;
    color: #aaaaaa;
    margin-top: 4px;
  }
  .clm-val-ok {
    color: #27ae60;
  }
  .clm-val-warn {
    color: #c8860a;
  }
  .clm-val-danger {
    color: #e74c3c;
  }
  .clm-val-approver {
    font-size: 14px;
    color: #000000;
  }

  /* Path badge */
  .clm-path-badge {
    display: inline-block;
    padding: 2px 8px;
    border-radius: 10px;
    font-size: 10px;
    font-weight: 700;
    margin-left: 8px;
    vertical-align: middle;
  }
  .clm-badge-tool {
    background: #000000;
    color: #FFF21A;
  }
  .clm-badge-nontool {
    background: #27ae60;
    color: #fff;
  }

  /* ── Alerts ── */
  .clm-alert {
    display: flex;
    align-items: flex-start;
    gap: 12px;
    padding: 12px 16px;
    border-radius: 6px;
    font-size: 14px;
    margin-top: 12px;
  }
  .clm-alert-icon {
    font-size: 18px;
    font-weight: 700;
    flex-shrink: 0;
    line-height: 1.4;
  }
  .clm-alert-danger {
    background: #fdf3f2;
    border: 1px solid #f5b7b1;
    color: #922b21;
  }
  .clm-alert-success {
    background: #eafaf1;
    border: 1px solid #a9dfbf;
    color: #1e8449;
  }

  /* Hierarchy strip */
  .clm-hierarchy-strip {
    margin-top: 16px;
    padding: 12px 16px;
    background: #fffde7;
    border: 1px solid #FFF21A;
    border-radius: 6px;
  }
  .clm-hierarchy-title {
    font-size: 11px;
    font-weight: 700;
    text-transform: uppercase;
    color: #888888;
    margin-bottom: 8px;
  }
  .clm-hierarchy-node {
    display: flex;
    align-items: center;
    gap: 10px;
    padding: 5px 0;
    border-bottom: 1px solid #fff0a0;
    font-size: 13px;
  }
  .clm-hierarchy-node:last-child {
    border-bottom: none;
  }
  .clm-hierarchy-level {
    font-size: 10px;
    font-weight: 700;
    color: #888888;
    min-width: 50px;
  }
  .clm-hierarchy-name {
    flex: 1;
    color: #000000;
    font-weight: 600;
  }
  .clm-hierarchy-limit {
    color: #c8860a;
    font-weight: 600;
  }

  /* ── Actions ── */
  .clm-actions {
    display: flex;
    justify-content: flex-end;
    gap: 12px;
    padding: 20px 28px;
    background: #f9f9f9;
    border: 1px solid #e0e0e0;
    border-top: none;
    border-radius: 0 0 8px 8px;
    flex-wrap: wrap;
  }
  .clm-btn {
    padding: 10px 24px;
    border-radius: 5px;
    font-size: 14px;
    font-weight: 600;
    cursor: pointer;
    border: none;
    transition: all 0.15s;
  }
  .clm-btn-primary {
    background: #000000;
    color: #FFF21A;
  }
  .clm-btn-primary:hover:not(:disabled) {
    background: #1a1a1a;
  }
  .clm-btn-primary:disabled {
    background: #aaaaaa;
    color: #ffffff;
    cursor: not-allowed;
  }
  .clm-btn-outline {
    background: transparent;
    color: #000000;
    border: 2px solid #000000;
  }
  .clm-btn-outline:hover:not(:disabled) {
    background: #fffde7;
    border-color: #000000;
  }
  .clm-btn-outline:disabled {
    opacity: 0.5;
    cursor: not-allowed;
  }

  /* ── Success Panel ── */
  .clm-success-panel {
    text-align: center;
    padding: 48px 28px;
    background: #fff;
    border: 1px solid #e0e0e0;
    border-top: none;
    border-radius: 0 0 8px 8px;
  }
  .clm-success-icon {
    width: 60px;
    height: 60px;
    background: #FFF21A;
    color: #000000;
    border-radius: 50%;
    font-size: 28px;
    display: flex;
    align-items: center;
    justify-content: center;
    margin: 0 auto 20px;
  }
  .clm-success-panel h3 {
    color: #000000;
    font-size: 20px;
    margin-bottom: 12px;
  }
  .clm-success-panel p {
    color: #4a4a4a;
    margin-bottom: 20px;
  }
  .clm-deviation-note {
    background: #fdf3f2;
    border: 1px solid #f5b7b1;
    color: #922b21;
    padding: 10px 16px;
    border-radius: 6px;
    margin-bottom: 20px;
    font-size: 13px;
  }

  /* ============================================================
     MULTI-SEGMENT CSS (UltraTech Theme)
     ============================================================ */

  .clm-ms-badge {
    display: inline-block;
    background: #FFF21A;
    color: #000000;
    font-size: 10px;
    font-weight: 700;
    padding: 2px 8px;
    border-radius: 10px;
    margin-left: 8px;
    vertical-align: middle;
    letter-spacing: 0.5px;
  }
  .clm-ms-toggle-row {
    padding: 12px 0 8px 0;
  }
  .clm-ms-toggle-label {
    font-size: 14px;
    color: #1a1a1a;
    cursor: pointer;
    display: flex;
    align-items: center;
    gap: 4px;
  }
  .clm-ms-panel {
    margin-top: 16px;
    border: 1px solid #e0e0e0;
    border-radius: 6px;
    overflow: hidden;
  }
  .clm-ms-method-row {
    padding: 14px 16px;
    background: #f9f9f9;
    border-bottom: 1px solid #e0e0e0;
  }
  .clm-ms-method-label {
    font-size: 11px;
    font-weight: 700;
    text-transform: uppercase;
    color: #888888;
    margin-bottom: 10px;
    display: block;
  }
  .clm-ms-method-options {
    display: flex;
    gap: 16px;
    flex-wrap: wrap;
  }
  .clm-ms-radio {
    display: flex;
    align-items: flex-start;
    gap: 8px;
    cursor: pointer;
    padding: 10px 14px;
    border: 1px solid #dddddd;
    border-radius: 5px;
    background: #fff;
    min-width: 160px;
    transition: border-color 0.15s, background 0.15s;
  }
  .clm-ms-radio:hover {
    border-color: #FFF21A;
    background: #fffde7;
  }
  .clm-ms-radio input[type="radio"] {
    margin-top: 2px;
    flex-shrink: 0;
    accent-color: #000000;
  }
  .clm-ms-radio-label strong {
    display: block;
    font-size: 13px;
    color: #000000;
  }
  .clm-ms-radio-label small {
    display: block;
    font-size: 11px;
    color: #888888;
    margin-top: 2px;
  }

  .clm-ms-table-header {
    display: flex;
    align-items: center;
    padding: 8px 14px;
    background: #f0f0f0;
    border-bottom: 1px solid #e0e0e0;
    font-size: 11px;
    font-weight: 700;
    text-transform: uppercase;
    color: #888888;
  }
  .clm-ms-table-row {
    display: flex;
    align-items: center;
    padding: 10px 14px;
    border-bottom: 1px solid #f5f5f5;
    background: #fff;
    gap: 4px;
  }
  .clm-ms-table-row:last-child {
    border-bottom: none;
  }
  .clm-ms-col-seg {
    flex: 1.8;
    display: flex;
    align-items: center;
    gap: 8px;
    font-weight: 600;
  }
  .clm-ms-col-num {
    flex: 1;
    text-align: right;
  }
  .clm-ms-seg-name {
    font-size: 14px;
    color: #000000;
  }
  .clm-ms-calc {
    font-weight: 600;
    font-size: 13px;
  }
  .clm-ms-input {
    width: 100%;
    padding: 6px 8px;
    border: 1px solid #cccccc;
    border-radius: 4px;
    font-size: 12px;
    text-align: right;
    box-sizing: border-box;
  }
  .clm-ms-input:focus {
    outline: none;
    border-color: #000000;
    box-shadow: 0 0 0 2px rgba(255, 242, 26, 0.4);
  }
  .clm-ms-input:disabled {
    background: #f5f5f5;
    color: #aaaaaa;
  }
  .clm-ms-input[readonly] {
    background: #f5f5f5;
    color: #888888;
  }

  .clm-ms-totals-row {
    display: flex;
    align-items: center;
    padding: 10px 14px;
    background: #f0f0f0;
    border-top: 2px solid #dddddd;
    font-size: 13px;
    gap: 4px;
  }
  .clm-ms-alert {
    display: flex;
    align-items: center;
    gap: 8px;
    padding: 10px 14px;
    font-size: 13px;
    font-weight: 600;
  }
  .clm-ms-alert-danger {
    background: #fdf3f2;
    color: #c0392b;
    border-top: 1px solid #f5b7b1;
  }
  .clm-ms-alert-success {
    background: #eafaf1;
    color: #1e8449;
    border-top: 1px solid #a9dfbf;
  }
  .clm-ms-hold-info {
    display: flex;
    align-items: flex-start;
    gap: 16px;
    padding: 20px;
    background: #fffde7;
    border-top: 2px solid #FFF21A;
  }
  .clm-ms-hold-icon {
    font-size: 28px;
    flex-shrink: 0;
  }
  .clm-ms-hold-info strong {
    display: block;
    font-size: 15px;
    color: #000000;
    margin-bottom: 6px;
  }
  .clm-ms-hold-info p {
    font-size: 13px;
    color: #4a4a4a;
    line-height: 1.6;
    margin: 0;
  }

  /* ============================================================
     TCL CSS (UltraTech Theme)
     ============================================================ */

  .clm-tcl-badge {
    display: inline-block;
    padding: 2px 8px;
    border-radius: 10px;
    font-size: 10px;
    font-weight: 700;
    margin-left: 8px;
    vertical-align: middle;
    letter-spacing: 0.5px;
  }
  .clm-tcl-badge-active {
    background: #FFF21A;
    color: #000000;
  }
  .clm-tcl-badge-info {
    background: #000000;
    color: #FFF21A;
  }

  .clm-tcl-existing {
    margin-bottom: 12px;
    padding: 10px 14px;
    background: #fffde7;
    border: 1px solid #FFF21A;
    border-radius: 5px;
  }
  .clm-tcl-existing-title {
    font-size: 11px;
    font-weight: 700;
    text-transform: uppercase;
    color: #888888;
    margin-bottom: 8px;
  }
  .clm-tcl-existing-row {
    display: flex;
    align-items: center;
    gap: 12px;
    font-size: 13px;
    padding: 4px 0;
    border-bottom: 1px solid #fff0a0;
  }
  .clm-tcl-existing-row:last-child {
    border-bottom: none;
  }
  .clm-tcl-existing-seg {
    font-weight: 700;
    color: #000000;
    min-width: 60px;
  }
  .clm-tcl-existing-amt {
    font-weight: 700;
    color: #c8860a;
  }
  .clm-tcl-existing-perm {
    color: #888888;
    font-size: 12px;
  }
  .clm-tcl-existing-date {
    color: #4a4a4a;
    margin-left: auto;
  }
  .clm-tcl-expiring {
    color: #e74c3c;
    font-weight: 700;
    font-size: 12px;
  }
  .clm-tcl-safe {
    color: #27ae60;
    font-size: 12px;
  }

  .clm-tcl-toggle-row {
    padding: 4px 0 8px 0;
  }
  .clm-tcl-toggle-label {
    font-size: 14px;
    color: #1a1a1a;
    cursor: pointer;
    display: flex;
    align-items: center;
    gap: 6px;
  }
  .clm-tcl-panel {
    margin-top: 16px;
    padding: 0;
    border: 1px solid #FFF21A;
    border-radius: 6px;
    overflow: hidden;
    background: #fffde7;
  }
  .clm-tcl-info-box {
    display: flex;
    align-items: flex-start;
    gap: 12px;
    padding: 14px 16px;
    background: #fffde7;
    border-bottom: 1px solid #FFF21A;
  }
  .clm-tcl-info-icon {
    font-size: 18px;
    color: #c8860a;
    flex-shrink: 0;
    margin-top: 1px;
  }
  .clm-tcl-info-text {
    font-size: 13px;
    color: #4a4a4a;
    line-height: 1.5;
  }
  .clm-tcl-info-text strong {
    color: #000000;
  }

  .clm-tcl-panel .clm-row {
    padding: 14px 16px;
  }

  .clm-tcl-calc-strip {
    display: flex;
    align-items: center;
    gap: 0;
    padding: 12px 16px;
    background: #fffde7;
    border-top: 1px solid #FFF21A;
    flex-wrap: wrap;
  }
  .clm-tcl-calc-item {
    display: flex;
    flex-direction: column;
    gap: 4px;
    padding: 0 16px;
    text-align: center;
  }
  .clm-tcl-calc-item:first-child {
    padding-left: 0;
  }
  .clm-tcl-calc-label {
    font-size: 10px;
    font-weight: 700;
    text-transform: uppercase;
    color: #888888;
  }
  .clm-tcl-calc-val {
    font-size: 16px;
    font-weight: 700;
    color: #000000;
  }
  .clm-tcl-calc-arrow {
    color: #bbbbbb;
    font-size: 18px;
    padding: 0 8px;
  }
  .clm-tcl-warning {
    padding: 10px 16px;
    background: #fffde7;
    border-top: 1px solid #FFF21A;
    font-size: 12px;
    color: #9a7d0a;
    font-weight: 600;
  }

  /* ============================================================
     FORCE FULL-WIDTH CLM WIDGET (ServiceNow Override)
     ============================================================ */

  .sn-widget-content,
  .sn-widget-content > div,
  .container,
  .container-fluid {
    width: 100% !important;
    max-width: 100% !important;
    padding-left: 0 !important;
    padding-right: 0 !important;
  }

  html,
  body {
    width: 100%;
  }

  /* Inner padding for full-width layout */
  .clm-header,
  .clm-section,
  .clm-calc-panel,
  .clm-actions,
  .clm-success-panel {
    padding-left: 24px;
    padding-right: 24px;
  }

  /* ============================================================
     TABLET BREAKPOINT — 768px
     ============================================================ */

  @media (max-width: 768px) {
    .clm-header {
      padding: 16px 20px;
    }

    .clm-title {
      font-size: 18px;
    }

    .clm-subtitle {
      font-size: 12px;
    }

    .clm-request-badge {
      padding: 3px 12px;
      font-size: 12px;
    }

    .clm-section {
      padding: 20px 20px;
    }

    .clm-section-title {
      font-size: 13px;
      margin-bottom: 16px;
    }

    .clm-section-num {
      width: 22px;
      height: 22px;
      font-size: 11px;
    }

    .clm-row {
      gap: 16px;
      margin-bottom: 14px;
    }

    .clm-field {
