sp_widget.script:
	(function() {

			var action = input && input.action;

			// ── searchCustomers (by PAN or Name, filtered by TSH) ─────
			if (action === 'searchCustomers') {

					var searchTerm = (input.searchTerm || '').trim();
					if (searchTerm.length < 3) { 
							data.customers = []; 
							return; 
					}

					// Get current user's TSH record
				var currentUserID = gs.getUserID();
				var tshGr = new GlideRecord('x_birl3_clm_tsh');
	tshGr.addQuery('name', gs.getUserID()); // ✅ correct
	tshGr.setLimit(1);
	tshGr.query();

	var tshSysId = '';
	if (tshGr.next()) {
			tshSysId = tshGr.sys_id + '';
	}

					// If no TSH record found, return empty
					if (!tshSysId) {
							data.customers = [];
							data.error = 'No TSH record found for current user';
							return;
					} 

					// Search customers by PAN or Name, filtered by TSH
					var custGr = new GlideRecord('x_birl3_clm_clm_customer_master1');
			//		custGr.addQuery('tsh', tshSysId); // Filter by TSH

					// Search by PAN or Customer Name
			var qc = custGr.addQuery('pan', 'CONTAINS', searchTerm);
qc.addOrCondition('customer_code_sap', 'CONTAINS', searchTerm);
					custGr.orderBy('customer_name');
					custGr.query();

				//Customer search tsh restricted






var customers = [];
while (custGr.next()) {

    // ✅ STEP 2 ADD HERE
    var isMyCustomer = (custGr.tsh + '' === tshSysId);

    // 🔥 FETCH SD MULTIPLIER
    var sdMultiplier = 1;
    var multGr = new GlideRecord('x_birl3_clm_clm_multiplier');
    multGr.addQuery('cg2_code', custGr.cg2_code + '');
    multGr.addQuery('segment', custGr.segment + '');
    multGr.addQuery('is_active', true);
    multGr.setLimit(1);
    multGr.query();

							// Get vintage days
							var vintageDays = 0;
							var fos = custGr.first_order_date + '';
							if (fos && fos !== '' && fos !== 'null') {
									var fd = new GlideDate(); 
									fd.setValue(fos);
									var td = new GlideDate();
									var dd = Math.floor((td.getNumericValue() - fd.getNumericValue()) / (1000 * 60 * 60 * 24));
									vintageDays = dd > 0 ? dd : 0;
							}

							// Get outstanding
							var outstanding = 0;
							var agGr = new GlideRecord('x_birl3_clm_clm_aging_snapshot');
							agGr.addQuery('customer', custGr.sys_id + '');
							agGr.orderByDesc('snapshot_month');
							agGr.setLimit(1);
							agGr.query();
							if (agGr.next()) outstanding = parseFloat(agGr.total_outstanding) || 0;

							// 🔥 PAN LEVEL SD CALCULATION

var panGr = new GlideRecord('x_birl3_clm_clm_customer_master1');
panGr.addQuery('pan', custGr.pan); // ONLY PAN
panGr.query();
var panLevelSD = 0;

while (panGr.next()) {
    panLevelSD += parseFloat(panGr.current_sd_amount) || 0;
}

	var agingTable = [];

var agGrFull = new GlideRecord('x_birl3_clm_clm_aging_snapshot');
agGrFull.addQuery('customer', custGr.sys_id + '');
agGrFull.orderByDesc('snapshot_month');
agGrFull.setLimit(6);
agGrFull.query();

while (agGrFull.next()) {
    agingTable.push({
        month: agGrFull.snapshot_month.getDisplayValue(),
        b0_30: parseFloat(agGrFull.bucket_0_30_days) || 0,
        b31_45: parseFloat(agGrFull.bucket_31_45_days) || 0,
        b46_60: parseFloat(agGrFull.bucket_46_60_days) || 0,
        b61_75: parseFloat(agGrFull.bucket_61_75_days) || 0,
        b76_90: parseFloat(agGrFull.bucket_76_90_days) || 0,
        b91_120: parseFloat(agGrFull.bucket_91_120_days) || 0,
