// 🔥 ADD THIS
gr.is_deviation = f.isDeviation;
							var sysId = gr.insert();
						// 🔥 SAVE TRADE CUSTOMERS (CHILD RECORDS)
	if (f.tradeCustomers && f.tradeCustomers.length > 0) {

